import { stdout } from std.io;
class Outer {
    private label: String = "outer";
    construct() { }
    class Nested { value: Int32 = 4; construct() { } }
    inner class Inner {
        construct() { }
        describe(): String { return outer.label; }
    }
    make(): String { inmut i = Inner(); return i.describe(); }
}
contract Nameable { name(): String; }
fn make_nameable(): Nameable {
    class Tmp implements Nameable {
        construct() { }
        name(): String { return "t"; }
    }
    return Tmp();
}
fn main(): Void {
    inmut n = Outer.Nested();
    stdout.println(n.value);
    inmut o = Outer();
    stdout.println(o.make());
    inmut i2 = o.Inner();
    stdout.println(i2.describe());
    stdout.println(make_nameable().name());
}
